import React, { useState, useEffect } from 'react';
import axios from 'axios';
import GridProductCard from './GridProductCard';
import FilterSidebar from './FilterSidebar';

const UnifiedProductGrid = ({ title, pageTarget }) => {
    const [products, setProducts] = useState([]);
    const [loading, setLoading] = useState(true);
    const [isFilterOpen, setIsFilterOpen] = useState(false);

    useEffect(() => {
        const fetchProducts = async () => {
            try {
                setLoading(true);
                const { data } = await axios.get('http://localhost:5001/api/products');
                // Filter products that belong to this specific page target
                // If it's undefined, we might just show all or show nothing.
                const filtered = data.filter(p => p.pages && p.pages.includes(pageTarget));
                setProducts(filtered);
            } catch (err) {
                console.error("Failed to fetch products for grid:", err);
            } finally {
                setLoading(false);
            }
        };

        if (pageTarget) fetchProducts();
    }, [pageTarget]);

    return (
        <div className="bg-white min-h-screen relative font-display">
            {/* Pill Navigation */}
            <div className="pt-2 pb-4 px-4 md:px-8">
                <div className="flex flex-wrap gap-2 mb-8">
                    <button className="px-3 py-1.5 bg-black text-white text-[10px] font-bold uppercase tracking-widest border border-black hover:bg-gray-800 transition-colors">View All</button>
                    <button className="px-3 py-1.5 bg-white text-gray-800 text-[10px] font-bold uppercase tracking-widest border border-gray-300 hover:border-black transition-colors">Accessories</button>
                    <button className="px-3 py-1.5 bg-white text-gray-800 text-[10px] font-bold uppercase tracking-widest border border-gray-300 hover:border-black transition-colors">Shoes</button>
                    <button className="px-3 py-1.5 bg-white text-gray-800 text-[10px] font-bold uppercase tracking-widest border border-gray-300 hover:border-black transition-colors">Clothes</button>
                </div>

                {/* Toolbar */}
                <div className="flex justify-between items-center border-t border-[#f1f1f1] pt-6 pr-2">
                    <button className="text-xs uppercase tracking-widest font-medium text-gray-800 flex items-center gap-1 hover:text-black">
                        Sort By 
                        <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-4 h-4 ml-0.5">
                          <path strokeLinecap="round" strokeLinejoin="round" d="M12 4.5v15m7.5-7.5h-15" />
                        </svg>
                    </button>

                    <button 
                        onClick={() => setIsFilterOpen(true)}
                        className="text-xs uppercase tracking-widest font-medium text-gray-800 flex items-center gap-2 hover:text-black"
                    >
                        Filter
                        <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-4 h-4">
                            <path strokeLinecap="round" strokeLinejoin="round" d="M10.5 6h9.75M10.5 6a1.5 1.5 0 1 1-3 0m3 0a1.5 1.5 0 1 0-3 0M3.75 6H7.5m3 12h9.75m-9.75 0a1.5 1.5 0 0 1-3 0m3 0a1.5 1.5 0 0 0-3 0m-3.75 0H7.5m9-6h3.75m-3.75 0a1.5 1.5 0 0 1-3 0m3 0a1.5 1.5 0 0 0-3 0m-9.75 0h9.75" />
                        </svg>
                    </button>
                </div>
            </div>

            {/* Grid Area */}
            {loading ? (
                <div className="flex justify-center items-center h-64 text-xs font-medium uppercase tracking-[0.2em] text-gray-400">
                    Loading Collection...
                </div>
            ) : products.length === 0 ? (
                <div className="flex justify-center items-center h-64 text-xs font-medium uppercase tracking-[0.2em] text-gray-400">
                    No items available at the moment.
                </div>
            ) : (
                <div className="px-4 md:px-8 bg-white border-t border-[#f1f1f1]">
                    <div className="grid grid-cols-2 md:grid-cols-4 gap-2 md:gap-4 pt-6">
                        {products.map(product => (
                            <GridProductCard key={product._id} product={product} />
                        ))}
                    </div>
                </div>
            )}

            {/* Filter Sidebar overlay */}
            <FilterSidebar 
                isOpen={isFilterOpen} 
                onClose={() => setIsFilterOpen(false)} 
                totalResults={products.length}
            />
        </div>
    );
};

export default UnifiedProductGrid;
